import numpy as np

def cond2(A):
    s = np.linalg.svd(np.asarray(A, dtype=float), compute_uv=False)
    return float(s[0] / s[-1])

def digits_lost(A):
    return round(float(np.log10(cond2(A))), 1)

def predicted_error(A, rel_db):
    return cond2(A) * rel_db
